CREATE OR REPLACE FUNCTION public.participating_countries() RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT count(DISTINCT p.country_code)::integer FROM public.profiles p JOIN public.season_entries e ON e.user_id = p.id WHERE p.show_on_public_board = true; $$; REVOKE ALL ON FUNCTION public.participating_countries() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.participating_countries() TO anon, authenticated;